/* ordena as perguntas de cada quiz por nível (básico -> avançado) */
(function () { var ord = { basico: 0, intermediario: 1, avancado: 2 }; Object.keys(TREINOS.QUIZ).forEach(function (k) { TREINOS.QUIZ[k].perguntas.sort(function (a, b) { return (ord[a.nivel] || 0) - (ord[b.nivel] || 0); }); }); })();
